class SecureBuffer {
public:
    explicit SecureBuffer(size_t size) : size_(size) {
        data_ = new unsigned char[size];
    }

    ~SecureBuffer() {
        if (data_) {
            OPENSSL_cleanse(data_, size_);
            delete[] data_;
        }
    }

    SecureBuffer(const SecureBuffer&) = delete;
    SecureBuffer& operator=(const SecureBuffer&) = delete;

    SecureBuffer(SecureBuffer&& other) noexcept 
        : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr;
        other.size_ = 0;
    }

    unsigned char* data() { return data_; }
    size_t size() const { return size_; }

private:
    unsigned char* data_;
    size_t size_;
};

struct CredentialEntry {
    std::string service_account;
    SecureBuffer token;
    uint64_t expiry_epoch;
    int refresh_count;

    CredentialEntry(const std::string& sa, SecureBuffer&& tok, uint64_t exp)
        : service_account(sa), token(std::move(tok)), expiry_epoch(exp), refresh_count(0) {}
};

class CredentialCache {
public:
    static CredentialCache& instance() {
        static CredentialCache cache;
        return cache;
    }

    bool store(const std::string& key, const std::string& sa,
              const unsigned char* token_data, size_t token_len, uint64_t expiry) {
        std::lock_guard<std::mutex> lock(mutex_);

        SecureBuffer buf(token_len);
        std::memcpy(buf.data(), token_data, token_len);

        auto it = cache_.find(key);
        if (it != cache_.end()) {
            cache_.erase(it);
        }

        cache_.emplace(key, 
            std::make_unique<CredentialEntry>(sa, std::move(buf), expiry));
        return true;
    }

    const CredentialEntry* lookup(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it == cache_.end()) return nullptr;
        return it->second.get();
    }

    void evict_expired(uint64_t current_epoch) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = cache_.begin(); it != cache_.end();) {
            if (it->second->expiry_epoch < current_epoch) {
                it = cache_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    CredentialCache() = default;
    std::mutex mutex_;
    std::unordered_map<std::string, std::unique_ptr<CredentialEntry>> cache_;
};

class TokenRefresher {
public:
    using RefreshCallback = std::function<bool(const std::string&, std::vector<unsigned char>&)>;

    TokenRefresher(RefreshCallback cb) : callback_(std::move(cb)) {}

    bool refresh(const std::string& service_account, const std::string& cache_key,
                uint64_t new_expiry) {
        std::vector<unsigned char> new_token;

        if (!callback_(service_account, new_token)) {
            return false;
        }

        if (new_token.empty()) return false;

        bool result = CredentialCache::instance().store(
            cache_key, service_account, new_token.data(), new_token.size(), new_expiry);

        // Clear the local token buffer
        OPENSSL_cleanse(new_token.data(), new_token.size());
        new_token.clear();

        return result;
    }

private:
    RefreshCallback callback_;
};

class K8sServiceAccountAuth {
public:
    K8sServiceAccountAuth(const std::string& namespace_name,
                          const std::string& service_account)
        : namespace_(namespace_name), service_account_(service_account) {}

    bool authenticate(const unsigned char* bearer_token, size_t token_len,
                     uint64_t expiry) {
        std::string cache_key = namespace_ + "/" + service_account_;
        return CredentialCache::instance().store(
            cache_key, service_account_, bearer_token, token_len, expiry);
    }

    std::string get_diagnostic_info() const {
        std::string cache_key = namespace_ + "/" + service_account_;
        auto* entry = CredentialCache::instance().lookup(cache_key);
        if (!entry) return "no cached credential";

        // Build diagnostic string with metadata only
        std::string info = "sa=" + entry->service_account + 
                          " expiry=" + std::to_string(entry->expiry_epoch) +
                          " refresh_count=" + std::to_string(entry->refresh_count);
        return info;
    }

    bool rotate_credentials(TokenRefresher& refresher, uint64_t new_expiry) {
        std::string cache_key = namespace_ + "/" + service_account_;
        auto* entry = CredentialCache::instance().lookup(cache_key);

        if (!entry) return false;

        // Log rotation attempt with non-sensitive metadata only
        std::string audit_context = build_audit_context(entry);
        log_rotation_attempt(audit_context);

        return refresher.refresh(service_account_, cache_key, new_expiry);
    }

private:
    std::string build_audit_context(const CredentialEntry* entry) {
        // Include first 32 bytes of token hash for correlation
        unsigned char hash[EVP_MAX_MD_SIZE];
        unsigned int hash_len = 0;

        EVP_MD_CTX* ctx = EVP_MD_CTX_new();
        if (!ctx) {
            // Fail safe: return metadata-only context if hashing unavailable
            return "sa=" + entry->service_account + " token_hash=unavailable";
        }
        if (EVP_DigestInit_ex(ctx, EVP_sha256(), nullptr) != 1 ||
            EVP_DigestUpdate(ctx, entry->token.data(), entry->token.size()) != 1 ||
            EVP_DigestFinal_ex(ctx, hash, &hash_len) != 1) {
            EVP_MD_CTX_free(ctx);
            return "sa=" + entry->service_account + " token_hash=unavailable";
        }
        EVP_MD_CTX_free(ctx);

        // Convert to hex for logging
        std::string hex_hash;
        hex_hash.reserve(hash_len * 2);
        for (unsigned int i = 0; i < hash_len; i++) {
            char buf[3];
            snprintf(buf, sizeof(buf), "%02x", hash[i]);
            hex_hash += buf;
        }

        return "sa=" + entry->service_account + " token_hash=" + hex_hash;
    }

    void log_rotation_attempt(const std::string& context) {
        // In production, this writes to structured logging
        // For now, append to rotation log buffer
        rotation_log_.push_back(context);
    }

    std::string namespace_;
    std::string service_account_;
    std::vector<std::string> rotation_log_;
};

class ConnectionPool {
public:
    struct Connection {
        std::string endpoint;
        bool in_use;

        Connection() : in_use(false) {}
    };

    ConnectionPool(size_t max_size) : max_size_(max_size) {
        pool_.resize(max_size);
    }

    Connection* acquire(const std::string& endpoint, 
                       const CredentialEntry* cred) {
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto& conn : pool_) {
            if (!conn.in_use) {
                conn.endpoint = endpoint;
                conn.in_use = true;
                return &conn;
            }
        }
        return nullptr;
    }

    void release(Connection* conn) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (conn) {
            conn->in_use = false;
        }
    }

private:
    size_t max_size_;
    std::vector<Connection> pool_;
    std::mutex mutex_;
};

